"use client";

import { useEffect, useMemo, useState } from "react";
import { onAuthStateChanged, signInAnonymously, type User } from "firebase/auth";
import { getFirebaseAuth } from "@/lib/firebase";

type Note = {
  id: string;
  title: string;
  content: string;
  created_at: string;
  updated_at: string;
};

function preview(note: Note) {
  const text = note.content.replace(/\s+/g, " ").trim();
  return text || "Empty note";
}

function relativeDate(value: string) {
  const date = new Date(value.replace(" ", "T") + (value.includes("Z") ? "" : "Z"));
  const minutes = Math.max(0, Math.round((Date.now() - date.getTime()) / 60000));
  if (minutes < 1) return "Updated just now";
  if (minutes < 60) return `Updated ${minutes}m ago`;
  const hours = Math.round(minutes / 60);
  if (hours < 24) return `Updated ${hours}h ago`;
  const days = Math.round(hours / 24);
  return `Updated ${days}d ago`;
}

function formatCreated(value: string) {
  return new Date(value.replace(" ", "T") + (value.includes("Z") ? "" : "Z")).toLocaleDateString("en-GB", {
    day: "numeric",
    month: "short",
    year: "numeric",
  });
}

export default function NotesApp() {
  const [user, setUser] = useState<User | null>(null);
  const [notes, setNotes] = useState<Note[]>([]);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState("");

  const selectedNote = notes.find((note) => note.id === selectedId) ?? null;
  const visibleNotes = useMemo(
    () => notes.filter((note) => `${note.title} ${note.content}`.toLowerCase().includes(query.toLowerCase())),
    [notes, query],
  );

  useEffect(() => {
    let unsubscribe = () => {};
    try {
      const firebaseAuth = getFirebaseAuth();
      unsubscribe = onAuthStateChanged(firebaseAuth, async (currentUser) => {
        try {
          const authenticatedUser = currentUser ?? (await signInAnonymously(firebaseAuth)).user;
      setUser(authenticatedUser);
      const token = await authenticatedUser.getIdToken();
      const response = await fetch("/api/notes", { headers: { Authorization: `Bearer ${token}` } });
      if (!response.ok) throw new Error("Unable to load notes");
      const loadedNotes = (await response.json()) as Note[];
      setNotes(loadedNotes);
      setSelectedId(loadedNotes[0]?.id ?? null);
        } catch {
          setError("Connect Firebase to start taking notes.");
        } finally {
          setIsLoading(false);
        }
      });
    } catch {
      setError("Connect Firebase to start taking notes.");
      setIsLoading(false);
    }
    return unsubscribe;
  }, []);

  async function request(path: string, options: RequestInit = {}) {
    if (!user) throw new Error("Not authenticated");
    const token = await user.getIdToken();
    return fetch(path, {
      ...options,
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${token}`, ...options.headers },
    });
  }

  async function createNote() {
    setError("");
    try {
      const response = await request("/api/notes", { method: "POST", body: JSON.stringify({}) });
      if (!response.ok) throw new Error();
      const note = (await response.json()) as Note;
      setNotes((current) => [note, ...current]);
      setSelectedId(note.id);
    } catch {
      setError("Could not create that note.");
    }
  }

  async function saveNote() {
    if (!selectedNote) return;
    setIsSaving(true);
    try {
      const response = await request(`/api/notes/${selectedNote.id}`, {
        method: "PATCH",
        body: JSON.stringify({ title: selectedNote.title, content: selectedNote.content }),
      });
      if (!response.ok) throw new Error();
      const saved = (await response.json()) as Note;
      setNotes((current) => [saved, ...current.filter((note) => note.id !== saved.id)]);
    } catch {
      setError("Could not save your changes.");
    } finally {
      setIsSaving(false);
    }
  }

  async function deleteNote() {
    if (!selectedNote || !window.confirm("Delete this note?")) return;
    try {
      const response = await request(`/api/notes/${selectedNote.id}`, { method: "DELETE" });
      if (!response.ok) throw new Error();
      const remaining = notes.filter((note) => note.id !== selectedNote.id);
      setNotes(remaining);
      setSelectedId(remaining[0]?.id ?? null);
    } catch {
      setError("Could not delete that note.");
    }
  }

  function updateSelected(field: "title" | "content", value: string) {
    setNotes((current) => current.map((note) => note.id === selectedId ? { ...note, [field]: value } : note));
  }

  if (isLoading) return <div className="loading-screen">Opening your notes...</div>;

  return (
    <main className="notes-shell">
      <aside className="sidebar">
        <div className="brand-row">
          <h1>My Notes</h1>
          <button className="icon-button" onClick={createNote} aria-label="Create a new note" title="New note">↗</button>
        </div>
        <button className="new-note" onClick={createNote}><span>+</span> New note</button>
        <label className="search-box">
          <span aria-hidden="true">⌕</span>
          <input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search notes..." aria-label="Search notes" />
        </label>
        <div className="note-list">
          {visibleNotes.map((note) => (
            <button className={`note-item ${note.id === selectedId ? "selected" : ""}`} key={note.id} onClick={() => setSelectedId(note.id)}>
              <span className="note-icon" aria-hidden="true">▱</span>
              <span className="note-summary"><strong>{note.title || "Untitled note"}</strong><small>{relativeDate(note.updated_at)}</small></span>
            </button>
          ))}
          {!visibleNotes.length && <p className="empty-list">No notes found</p>}
        </div>
        <div className="sidebar-footer"><span className="status-dot" /> Saved privately to your account</div>
      </aside>

      <section className="editor-area">
        <header className="topbar">
          <span className="breadcrumb">Notes <span>/</span> {selectedNote?.title || "New note"}</span>
          <div className="profile-actions"><button className="theme-button" aria-label="Toggle theme" title="Toggle theme">☼</button><span className="avatar">{user?.uid.slice(0, 2).toUpperCase() || "ME"}</span><span className="chevron">⌄</span></div>
        </header>
        {error && <div className="error-banner">{error}</div>}
        {selectedNote ? <article className="editor">
          <div className="editor-heading">
            <div><input className="title-input" value={selectedNote.title} onChange={(event) => updateSelected("title", event.target.value)} placeholder="Untitled note" aria-label="Note title" /><p className="metadata">Last updated {relativeDate(selectedNote.updated_at).replace("Updated ", "").toLowerCase()} <span>•</span> Created {formatCreated(selectedNote.created_at)}</p></div>
            <div className="editor-actions"><button onClick={saveNote} disabled={isSaving} className="save-button">{isSaving ? "Saving..." : "Save"}</button><button className="icon-button muted" onClick={deleteNote} aria-label="Delete note" title="Delete note">⌫</button><button className="icon-button muted" aria-label="More actions" title="More actions">⋮</button></div>
          </div>
          <textarea className="content-input" value={selectedNote.content} onChange={(event) => updateSelected("content", event.target.value)} placeholder="Start writing..." aria-label="Note content" />
        </article> : <div className="empty-editor"><div className="empty-mark">✦</div><h2>Your thinking space</h2><p>Create a note to capture an idea, a plan, or anything worth keeping.</p><button className="new-note dark" onClick={createNote}>Create your first note</button></div>}
      </section>
    </main>
  );
}
